/**
 * ==========================================================================================
 * COMPOSANT : CameraRecognition.jsx
 * DESCRIPTION : Système de pointage biométrique par reconnaissance faciale.
 * FONCTIONNALITÉS : Capture unique, Scan continu 10s, Comparaison de photos, Gestion API.
 * VERSION : 4.2.0 (Optimisée pour la stabilité du flux vidéo)
 * ==========================================================================================
 */

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

// ==========================================================================================
// CONSTANTES & CONFIGURATION
// ==========================================================================================
const THEME = {
    colors: {
        primary: '#4F46E5',
        primaryDark: '#3730A3',
        primaryLight: '#EEF2FF',
        success: '#10B981',
        successDark: '#059669',
        successLight: '#ECFDF5',
        danger: '#EF4444',
        dangerDark: '#B91C1C',
        dangerLight: '#FEF2F2',
        warning: '#F59E0B',
        warningLight: '#FFFBEB',
        textMain: '#1E293B',
        textMuted: '#64748B',
        border: '#E2E8F0',
        background: '#F1F5F9',
        surface: '#FFFFFF',
        overlay: 'rgba(0, 0, 0, 0.75)',
        glass: 'rgba(255, 255, 255, 0.7)'
    },
    shadows: {
        sm: '0 1px 2px 0 rgba(0, 0, 0, 0.05)',
        md: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
        lg: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
        xl: '0 20px 25px -5px rgba(0, 0, 0, 0.1)'
    }
};

const SCAN_CONFIG = {
    DURATION_MS: 10000,
    API_INTERVAL_MS: 600,
    UI_REFRESH_MS: 50,
    MIN_CONFIDENCE_THRESHOLD: 0.35,
    VIDEO_CONSTRAINTS: {
        width: { ideal: 1280 },
        height: { ideal: 720 },
        facingMode: "user"
    }
};

// ==========================================================================================
// COMPOSANTS UI ATOMIQUES
// ==========================================================================================

/**
 * Affiche un badge de statut avec une animation de pulsation.
 */
const StatusIndicator = ({ status, isDetecting }) => {
    const config = {
        active: { color: THEME.colors.success, label: 'SYSTÈME PRÊT' },
        inactive: { color: THEME.colors.danger, label: 'SYSTÈME ARRÊTÉ' },
        scanning: { color: THEME.colors.warning, label: 'ANALYSE EN COURS' }
    };

    const current = isDetecting ? config.scanning : (status ? config.active : config.inactive);

    return (
        <div style={{ ...styles.statusBadge, backgroundColor: current.color }}>
            <div style={styles.pulseDot} />
            <span style={{ letterSpacing: '0.05em' }}>{current.label}</span>
        </div>
    );
};

/**
 * Affiche une ligne d'information clé/valeur pour les résultats.
 */
const DataField = ({ label, value, highlight = false }) => (
    <div style={styles.dataFieldRow}>
        <span style={styles.dataFieldLabel}>{label}</span>
        <span style={{ 
            ...styles.dataFieldValue, 
            color: highlight ? THEME.colors.primary : THEME.colors.textMain,
            fontWeight: highlight ? '700' : '500'
        }}>
            {value || '---'}
        </span>
    </div>
);

// ==========================================================================================
// COMPOSANT PRINCIPAL
// ==========================================================================================
const CameraRecognition = ({ addNotification }) => {
    // --- RÉFÉRENCES (DOM & TIMERS) ---
    const videoRef = useRef(null);
    const streamRef = useRef(null);
    const canvasRef = useRef(null);
    const scanIntervalRef = useRef(null);
    const scanTimeoutRef = useRef(null);
    const progressIntervalRef = useRef(null);

    // --- ÉTATS DE CONTRÔLE ---
    const [isCameraActive, setIsCameraActive] = useState(false);
    const [isVideoLoaded, setIsVideoLoaded] = useState(false);
    const [isDetecting, setIsDetecting] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [permissionStatus, setPermissionStatus] = useState('prompt');

    // --- ÉTATS DE DONNÉES ---
    const [scanProgress, setScanProgress] = useState(0);
    const [processedFrames, setProcessedFrames] = useState(0);
    const [error, setError] = useState(null);
    const [matchData, setMatchData] = useState(null);
    const [capturedImage, setCapturedImage] = useState(null);
    const [referenceImage, setReferenceImage] = useState(null);

    // ======================================================================================
    // LOGIQUE DE GESTION DE LA CAMÉRA
    // ======================================================================================

    /**
     * Initialise le canvas hors-écran pour les captures.
     */
    useEffect(() => {
        canvasRef.current = document.createElement('canvas');

        // Surveillance des permissions (Chrome/Firefox)
        if (navigator.permissions && navigator.permissions.query) {
            navigator.permissions.query({ name: 'camera' }).then(res => {
                setPermissionStatus(res.state);
                res.onchange = () => setPermissionStatus(res.state);
            });
        }
    }, []);

    /**
     * Arrête proprement tous les flux et nettoie les timers.
     */
    const terminateCamera = useCallback(() => {
        console.log("[Camera] Procédure d'arrêt lancée...");

        // 1. Nettoyage des processus asynchrones
        if (scanIntervalRef.current) clearInterval(scanIntervalRef.current);
        if (scanTimeoutRef.current) clearTimeout(scanTimeoutRef.current);
        if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);

        // 2. Libération du matériel
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => {
                track.stop();
                console.log(`[Camera] Track ${track.kind} libéré.`);
            });
            streamRef.current = null;
        }

        // 3. Reset des états UI
        if (videoRef.current) videoRef.current.srcObject = null;
        setIsCameraActive(false);
        setIsVideoLoaded(false);
        setIsDetecting(false);
        setScanProgress(0);
    }, []);

    /**
     * Tente d'activer la caméra avec une gestion de "Force Start".
     */
    const bootCamera = async () => {
        console.log("[Camera] Initialisation du matériel...");
        setError(null);
        setIsLoading(true);

        try {
            // Nettoyage préalable
            terminateCamera();

            // Demande d'accès au flux
            const stream = await navigator.mediaDevices.getUserMedia({
                video: SCAN_CONFIG.VIDEO_CONSTRAINTS,
                audio: false
            });

            console.log("[Camera] Flux reçu avec succès.");
            streamRef.current = stream;

            if (videoRef.current) {
                // Liaison du flux à la balise vidéo
                videoRef.current.srcObject = stream;

                // Forcer la lecture (Hack pour navigateurs mobiles et Safari)
                videoRef.current.onloadedmetadata = () => {
                    videoRef.current.play()
                        .then(() => {
                            console.log("[Video] Lecture démarrée.");
                            setIsVideoLoaded(true);
                            setIsCameraActive(true);
                            setIsLoading(false);
                            addNotification?.('Caméra activée', 'success');
                        })
                        .catch(e => {
                            console.error("[Video] Échec de lecture directe:", e);
                            setError("La lecture vidéo a été bloquée par le navigateur.");
                            setIsLoading(false);
                        });
                };
            }
        } catch (err) {
            console.error("[Camera] Erreur critique:", err);
            let userMessage = "Impossible d'accéder à la caméra.";

            if (err.name === 'NotAllowedError') userMessage = "L'accès à la caméra a été refusé. Veuillez vérifier les paramètres de votre navigateur.";
            if (err.name === 'NotFoundError') userMessage = "Aucun périphérique caméra trouvé.";
            if (err.name === 'NotReadableError') userMessage = "La caméra est déjà utilisée par une autre application.";

            setError(userMessage);
            setIsLoading(false);
            addNotification?.(userMessage, 'error');
        }
    };

    // ======================================================================================
    // LOGIQUE DE TRAITEMENT D'IMAGE
    // ======================================================================================

    /**
     * Capture la frame actuelle de la vidéo et la convertit en Base64.
     */
    const captureFrameAsBase64 = useCallback((quality = 0.85) => {
        if (!videoRef.current || !isVideoLoaded) return null;

        const video = videoRef.current;
        const canvas = canvasRef.current;

        // Synchronisation des dimensions
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;

        const ctx = canvas.getContext('2d');

        // Application d'un effet miroir pour correspondre au retour visuel
        ctx.translate(canvas.width, 0);
        ctx.scale(-1, 1);

        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

        return canvas.toDataURL('image/jpeg', quality);
    }, [isVideoLoaded]);

    /**
     * Traite un résultat positif de l'API de reconnaissance.
     */
    const finalizeMatch = async (data, capturedImg) => {
        setCapturedImage(capturedImg);

        const timestamp = new Date().toLocaleTimeString('fr-FR', {
            hour: '2-digit', minute: '2-digit', second: '2-digit'
        });

        setMatchData({
            name: data.student,
            email: data.email || 'Non renseigné',
            confidence: (data.confidence * 100).toFixed(1),
            attendanceId: data.attendance_id || 'ID_GÉNÉRÉ_' + Math.random().toString(36).substr(2, 9),
            time: timestamp
        });

        // Tentative de récupération de l'image de profil d'origine
        try {
            if (data.student_id) {
                const res = await studentsAPI.getById(data.student_id);
                if (res?.data?.photo_url) setReferenceImage(res.data.photo_url);
            }
        } catch (e) {
            console.warn("[API] Échec de récupération de la photo d'enrôlement.");
        }

        setIsDetecting(false);
        addNotification?.(`Pointage réussi : ${data.student}`, 'success');
    };

    // ======================================================================================
    // MODES DE CAPTURE
    // ======================================================================================

    /**
     * Mode SCAN COMPLET (10 secondes de tentatives répétées)
     */
    const startAutomatedScan = () => {
        if (!isCameraActive || isDetecting) return;

        console.log("[Scan] Démarrage du cycle 10s...");
        setIsDetecting(true);
        setScanProgress(0);
        setProcessedFrames(0);
        setMatchData(null);
        setReferenceImage(null);
        setError(null);

        let bestResult = null;
        const startTime = Date.now();

        // 1. Boucle de capture et d'appel API
        scanIntervalRef.current = setInterval(async () => {
            const currentFrame = captureFrameAsBase64(0.7);
            if (!currentFrame) return;

            setProcessedFrames(prev => prev + 1);

            try {
                const response = await attendanceAPI.recognize(currentFrame);
                const result = response?.data;

                if (result?.success && result?.confidence > SCAN_CONFIG.MIN_CONFIDENCE_THRESHOLD) {
                    // On garde le meilleur résultat (plus haute confiance) sur les 10s
                    if (!bestResult || result.confidence > bestResult.confidence) {
                        bestResult = { ...result, frame: currentFrame };
                        console.log(`[Scan] Meilleur candidat : ${result.student} (${result.confidence})`);
                    }
                }
            } catch (err) {
                console.warn("[Scan] Erreur sur une frame API.");
            }
        }, SCAN_CONFIG.API_INTERVAL_MS);

        // 2. Boucle de mise à jour de la progression UI
        progressIntervalRef.current = setInterval(() => {
            const elapsed = Date.now() - startTime;
            const progress = Math.min(100, (elapsed / SCAN_CONFIG.DURATION_MS) * 100);
            setScanProgress(progress);
        }, SCAN_CONFIG.UI_REFRESH_MS);

        // 3. Fin automatique du cycle
        scanTimeoutRef.current = setTimeout(() => {
            clearInterval(scanIntervalRef.current);
            clearInterval(progressIntervalRef.current);

            if (bestResult) {
                finalizeMatch(bestResult, bestResult.frame);
            } else {
                setIsDetecting(false);
                setError("Échec du scan : aucun visage n'a été reconnu durant les 10 secondes.");
                addNotification?.("Aucun résultat trouvé", "warning");
            }
        }, SCAN_CONFIG.DURATION_MS);
    };

    /**
     * Capture unique et immédiate
     */
    const performInstantCapture = async () => {
        if (!isVideoLoaded || isLoading) return;

        setIsLoading(true);
        setError(null);
        setMatchData(null);
        const frame = captureFrameAsBase64(0.92);

        try {
            const response = await attendanceAPI.recognize(frame);
            if (response?.data?.success) {
                finalizeMatch(response.data, frame);
            } else {
                setError(response?.data?.message || "L'identité n'a pas pu être établie.");
                addNotification?.("Inconnu", "error");
            }
        } catch (e) {
            setError("Erreur réseau ou serveur lors de la reconnaissance.");
        } finally {
            setIsLoading(false);
        }
    };

    /**
     * Nettoyage lors du démontage du composant
     */
    useEffect(() => {
        return () => terminateCamera();
    }, [terminateCamera]);

    // ======================================================================================
    // RENDU DU COMPOSANT
    // ======================================================================================

    return (
        <div style={styles.appContainer}>
            {/* EN-TETE DU MODULE */}
            <header style={styles.moduleHeader}>
                <div style={styles.branding}>
                    <div style={styles.iconBox}>
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>
                    </div>
                    <div>
                        <h1 style={styles.titleText}>Reconnaissance Faciale</h1>
                        <p style={styles.subTitleText}>Interface de pointage automatisée</p>
                    </div>
                </div>
                <div style={styles.systemStatus}>
                    <div style={styles.statusLabel}>
                        Statut Permission : <span style={{ fontWeight: '700', color: permissionStatus === 'granted' ? THEME.colors.success : THEME.colors.warning }}>{permissionStatus.toUpperCase()}</span>
                    </div>
                </div>
            </header>

            {/* ZONE PRINCIPALE : GRID 2 COLONNES */}
            <main style={styles.mainGrid}>

                {/* COLONNE GAUCHE : CAMÉRA */}
                <section style={styles.cameraCard}>
                    <div style={styles.videoStage}>
                        {isCameraActive ? (
                            <video
                                ref={videoRef}
                                autoPlay
                                playsInline
                                muted
                                style={styles.videoStream}
                            />
                        ) : (
                            <div style={styles.cameraStandby} onClick={bootCamera}>
                                <div style={styles.standbyIcon}>📷</div>
                                <h3 style={{ margin: '10px 0', color: THEME.colors.textMain }}>Caméra Inactive</h3>
                                <p style={{ color: THEME.colors.textMuted, fontSize: '0.9rem', marginBottom: '20px' }}>Cliquez pour initialiser le flux vidéo</p>
                                <button style={styles.primaryBtn} disabled={isLoading}>
                                    {isLoading ? 'Initialisation...' : 'ALLUMER LA CAMÉRA'}
                                </button>
                            </div>
                        )}

                        {/* Overlays Dynamiques */}
                        {isCameraActive && <StatusIndicator status={isCameraActive} isDetecting={isDetecting} />}

                        {isDetecting && <div style={styles.scannerAnimation} />}

                        {isDetecting && (
                            <div style={styles.frameCounter}>
                                Frames analysées : {processedFrames}
                            </div>
                        )}

                        {/* Barre de progression du scan */}
                        {isDetecting && (
                            <div style={styles.scanProgressTrack}>
                                <div style={{ ...styles.scanProgressFill, width: `${scanProgress}%` }} />
                            </div>
                        )}
                    </div>

                    {/* ACTIONS DE CONTRÔLE */}
                    <div style={styles.controlsArea}>
                        {!isCameraActive ? (
                            <button onClick={bootCamera} style={styles.fullWidthBtn} disabled={isLoading}>
                                DÉMARRER LE SYSTÈME DE CAPTURE
                            </button>
                        ) : (
                            <div style={styles.btnCluster}>
                                <button 
                                    onClick={performInstantCapture} 
                                    disabled={isDetecting || isLoading}
                                    style={{...styles.controlBtn, backgroundColor: THEME.colors.primary}}
                                >
                                    {isLoading ? 'TRAITEMENT...' : '📸 CAPTURE DIRECTE'}
                                </button>
                                <button 
                                    onClick={startAutomatedScan} 
                                    disabled={isDetecting}
                                    style={{...styles.controlBtn, backgroundColor: THEME.colors.warning}}
                                >
                                    🔍 SCAN INTELLIGENT (10s)
                                </button>
                                <button 
                                    onClick={terminateCamera} 
                                    style={{...styles.controlBtn, backgroundColor: THEME.colors.danger}}
                                >
                                    🛑 DÉCONNECTER
                                </button>
                            </div>
                        )}
                    </div>

                    {/* GESTION DES ERREURS */}
                    {error && (
                        <div style={styles.errorAlert}>
                            <div style={styles.errorTitle}>⚠️ Erreur Système</div>
                            <div style={styles.errorText}>{error}</div>
                        </div>
                    )}
                </section>

                {/* COLONNE DROITE : RÉSULTATS & INFO */}
                <aside style={styles.infoPanel}>
                    {matchData ? (
                        <div style={styles.resultView}>
                            <div style={styles.resultHeader}>
                                <h2 style={styles.resultTitle}>Identité Confirmée</h2>
                                <div style={styles.successBadge}>Validé</div>
                            </div>

                            <div style={styles.comparisonStage}>
                                <div style={styles.comparisonItem}>
                                    <span style={styles.comparisonLabel}>CAPTURE LIVE</span>
                                    <div style={styles.comparisonFrame}>
                                        <img src={capturedImage} style={styles.fitImage} alt="Capture Live" />
                                    </div>
                                </div>
                                <div style={styles.comparisonItem}>
                                    <span style={styles.comparisonLabel}>PHOTO DOSSIER</span>
                                    <div style={styles.comparisonFrame}>
                                        {referenceImage ? (
                                            <img src={referenceImage} style={styles.fitImage} alt="Dossier" />
                                        ) : (
                                            <div style={styles.imagePlaceholder}>N/A</div>
                                        )}
                                    </div>
                                </div>
                            </div>

                            <div style={styles.statsCard}>
                                <DataField label="Nom Complet" value={matchData.name} highlight />
                                <DataField label="Taux de Confiance" value={`${matchData.confidence}%`} highlight />
                                <DataField label="Adresse Email" value={matchData.email} />
                                <DataField label="Identifiant Unique" value={matchData.attendanceId} />
                                <DataField label="Heure de Passage" value={matchData.time} />
                            </div>

                            <button onClick={() => setMatchData(null)} style={styles.resetBtn}>
                                NOUVELLE IDENTIFICATION
                            </button>
                        </div>
                    ) : (
                        <div style={styles.emptyPanel}>
                            <div style={styles.emptyIllustration}>👤</div>
                            <h3 style={{ margin: '0 0 10px 0' }}>En attente de scan</h3>
                            <p style={{ margin: 0, fontSize: '0.85rem' }}>Les détails de l'étudiant apparaîtront ici après une détection réussie.</p>
                        </div>
                    )}
                </aside>
            </main>

            {/* BARRE DE PIED DE PAGE TECHNIQUE */}
            <footer style={styles.techFooter}>
                <div>Résolution Native : {isVideoLoaded ? `${videoRef.current.videoWidth}x${videoRef.current.videoHeight}` : '---'}</div>
                <div>Status API : CONNECTÉ</div>
                <div>Logiciel : BiometricGate v4.2.0</div>
            </footer>

            {/* INJECTION DES ANIMATIONS CSS GLOBALES */}
            <style dangerouslySetInnerHTML={{ __html: `
                @keyframes pulse-anim {
                    0% { transform: scale(0.95); opacity: 0.8; }
                    50% { transform: scale(1.05); opacity: 1; }
                    100% { transform: scale(0.95); opacity: 0.8; }
                }
                @keyframes scan-anim {
                    0% { transform: translateY(0); }
                    50% { transform: translateY(100%); }
                    100% { transform: translateY(0); }
                }
                button:active { transform: scale(0.98); }
                button:hover { filter: brightness(1.1); }
            ` }} />
        </div>
    );
};

